import re
def solve(s):
    toks = re.findall(r'\d+|[-+*/()]', s)
    pos = [0]
    def peek(): return toks[pos[0]] if pos[0] < len(toks) else None
    def take():
        pos[0] += 1; return toks[pos[0]-1]
    def atom():
        t = take()
        if t == '(':
            v = expr(); take(); return v
        if t == '-': return -atom()
        return int(t)
    def term():
        v = atom()
        while peek() in ('*', '/'):
            v = v * atom() if take() == '*' else v // atom()
        return v
    def expr():
        v = term()
        while peek() in ('+', '-'):
            v = v + term() if take() == '+' else v - term()
        return v
    return expr()

