import heapq
def solve(edges, start, goal):
    adj = {}
    for e in edges.split():
        ab, w = e.split(':'); a, b = ab.split('-')
        adj.setdefault(a, []).append((b, int(w))); adj.setdefault(b, []).append((a, int(w)))
    dist = {start: 0}; h = [(0, start)]
    while h:
        d, u = heapq.heappop(h)
        if u == goal: return d
        if d > dist.get(u, 1 << 60): continue
        for v, w in adj.get(u, []):
            if d + w < dist.get(v, 1 << 60):
                dist[v] = d + w; heapq.heappush(h, (d + w, v))
    return -1
